-- 3. Status history ------------------------------------------
CREATE TABLE IF NOT EXISTS "status_history" (
  "id"             TEXT NOT NULL,
  "organizationId" TEXT NOT NULL,
  "entityType"     TEXT NOT NULL,
  "entityId"       TEXT NOT NULL,
  "fromStatus"     TEXT,
  "toStatus"       TEXT NOT NULL,
  "changedById"    TEXT,
