-- ------------------------------------------------------------------
-- 2026-08-v3-phase1-roles-designations.sql
-- ------------------------------------------------------------------

-- V3 Phase 1 — four-role model + dynamic designations.
--
-- The structural half (UserRole gains SMM/TEAM, the designations table,
-- users.designationId, organizations.requireAssignmentApproval) is applied by
-- `prisma db push`. This file is the DATA half: it moves existing users onto
-- the new tiers and gives every organization a starting set of job labels.
-- Idempotent — safe to re-run.

BEGIN;

-- ─────────────────────────────────────────────────────────────
-- 1. v2's MEMBER tier becomes v3's TEAM. MEMBER stays in the enum
--    as a deprecated value so any row this misses still reads.
-- ─────────────────────────────────────────────────────────────
UPDATE users SET role = 'TEAM' WHERE role = 'MEMBER';

-- ─────────────────────────────────────────────────────────────
-- 2. Seed the default job labels for every organization.
--    SME and POC can't have work assigned to them — they're advisory
--    roles, so they're excluded from assignment pickers.
-- ─────────────────────────────────────────────────────────────
INSERT INTO designations ("id", "organizationId", "name", "slug", "isActive", "canBeAssignedWork", "sortOrder", "createdAt", "updatedAt")
SELECT
  'desg_' || o.id || '_' || d.slug,
  o.id, d.name, d.slug, TRUE, d.assignable, d.ord, NOW(), NOW()
FROM organizations o
CROSS JOIN (VALUES
  ('Editor',       'editor',       TRUE,  0),
  ('Photographer', 'photographer', TRUE,  1),
  ('Videographer', 'videographer', TRUE,  2),
  ('Copywriter',   'copywriter',   TRUE,  3),
  ('Designer',     'designer',     TRUE,  4),
  ('Head of Design','head-of-design', TRUE, 6),
  ('SME',          'sme',          FALSE, 7),
  ('POC',          'poc',          FALSE, 8)
) AS d(name, slug, assignable, ord)
ON CONFLICT ("organizationId", "slug") DO NOTHING;

-- ─────────────────────────────────────────────────────────────
-- 3. Carry each user's old enum designation onto the new FK, so
--    nobody loses their job label in the move.
--
--    v2's enum had an SMM value, but v3 makes SMM a ROLE — planning
--    is an access tier, not a craft — so it has no designation to
--    map onto and is deliberately absent below.
-- ─────────────────────────────────────────────────────────────
UPDATE users u
   SET "designationId" = d.id
  FROM designations d
 WHERE d."organizationId" = u."organizationId"
   AND u."designationId" IS NULL
   AND u.designation IS NOT NULL
   AND d.slug = CASE u.designation::text
                  WHEN 'DESIGNER'       THEN 'designer'
                  WHEN 'EDITOR'         THEN 'editor'
                  WHEN 'HEAD_OF_DESIGN' THEN 'head-of-design'
                  WHEN 'PHOTOGRAPHER'   THEN 'photographer'
                  WHEN 'SME'            THEN 'sme'
                  WHEN 'POC'            THEN 'poc'
                  ELSE NULL
                END;

COMMIT;


-- ------------------------------------------------------------------
-- 2026-08-v3-phase2-project-commercial.sql
-- ------------------------------------------------------------------

-- V3 Phase 2 — the project becomes the commercial unit.
--
-- Structure (Project.cycleAmount/cycleUnit/cycleStartDate/cycleEndDate,
-- project_deliverables, project_cycles, project_members.addedById,
-- Task.kind, the ProjectRole/CycleUnit/CycleStatus/TaskKind enums) is
-- applied by `prisma db push`. This mirrors it for other environments and
-- carries the one piece of data movement that push can't do.
-- Idempotent — safe to re-run.

BEGIN;

-- ─────────────────────────────────────────────────────────────
-- Projects created before v3 have startDate/endDate but no cycle
-- window, so they'd generate no cycles and their Plan tab would be
-- empty. Seed the cycle period from the dates they already have.
-- ─────────────────────────────────────────────────────────────
UPDATE projects
   SET "cycleStartDate" = "startDate"
 WHERE "cycleStartDate" IS NULL
   AND "startDate" IS NOT NULL;

UPDATE projects
   SET "cycleEndDate" = "endDate"
 WHERE "cycleEndDate" IS NULL
   AND "endDate" IS NOT NULL
   -- A retainer with an end date is unusual; leave open-ended ones alone.
   AND type = 'ONE_TIME';

COMMIT;

-- Cycles themselves are generated lazily by lib/cycles.ts (ensureCycles),
-- which runs whenever a project's cycles are read, so there's nothing to
-- backfill here. Client packages are converted to retainer projects by
-- scripts/migrate-packages-to-projects.ts, which is idempotent and must be
-- run once per environment:
--
--   npx tsx scripts/migrate-packages-to-projects.ts --dry-run
--   npx tsx scripts/migrate-packages-to-projects.ts


-- ------------------------------------------------------------------
-- 2026-08-v3-phase3-planning.sql
-- ------------------------------------------------------------------

-- V3 Phase 3 — the SMM planning surface.
--
-- Structure (ContentItem.cycleId/billingIntent/carryMode/submittedAt/
-- approvedAt, the BillingIntent and CarryMode enums, and the SUBMITTED /
-- APPROVED / CHANGES_REQUESTED / CARRIED_FORWARD content statuses) is
-- applied by `prisma db push`. This mirrors it and carries the backfill.
-- Idempotent — safe to re-run.

BEGIN;

-- ─────────────────────────────────────────────────────────────
-- Items already flagged as extras under v2 carry that meaning
-- forward, so cycle close (Phase 6) sees them as billable rather
-- than silently folding them into the package.
-- ─────────────────────────────────────────────────────────────
UPDATE content_items
   SET "billingIntent" = 'EXTRA_BILLABLE'
 WHERE "isExtra" = TRUE
   AND "billingIntent" = 'INCLUDED';

-- ─────────────────────────────────────────────────────────────
-- Attach existing project-linked items to the cycle their date
-- falls in. Items planned against a client but no project keep a
-- null cycleId and still render — the client roll-up reads them
-- by date, not by cycle.
-- ─────────────────────────────────────────────────────────────
UPDATE content_items ci
   SET "cycleId" = pc.id
  FROM project_cycles pc
 WHERE ci."cycleId" IS NULL
   AND ci."projectId" = pc."projectId"
   AND ci.date >= pc."startDate"
   AND ci.date <= pc."endDate";

COMMIT;

-- ------------------------------------------------------------------
-- 2026-08-v3-phase4-junior-workspace.sql
-- ------------------------------------------------------------------

-- V3 Phase 4 — the junior's workspace.
--
-- Structure (Task.kind/revision/approverId/submittedAt/approvedAt/cycleId and
-- the CHANGES_REQUESTED task status) is applied by `prisma db push`. This
-- mirrors it and carries the data movement.
-- Idempotent — safe to re-run.

BEGIN;

-- ─────────────────────────────────────────────────────────────
-- 1. Custom task lists are retired: v3 has My List plus one
--    automatic list per project. Fold every personal item that
--    lived in a custom list back into My List so nothing is lost
--    (the list rows themselves stay for one release, unused).
-- ─────────────────────────────────────────────────────────────
UPDATE personal_items
   SET "listId" = NULL
 WHERE "listId" IS NOT NULL;

-- ─────────────────────────────────────────────────────────────
-- 2. Tasks that already point at a content item are content work
--    by definition, so they read correctly in the new lists.
-- ─────────────────────────────────────────────────────────────
UPDATE tasks
   SET kind = 'CONTENT_WORK'
 WHERE kind = 'GENERAL'
   AND "contentItemId" IS NOT NULL
   AND "deletedAt" IS NULL;

-- ─────────────────────────────────────────────────────────────
-- 3. Attach existing project tasks to the cycle their due date
--    falls in, so Phase 6's cycle close sees them.
-- ─────────────────────────────────────────────────────────────
UPDATE tasks t
   SET "cycleId" = pc.id
  FROM project_cycles pc
 WHERE t."cycleId" IS NULL
   AND t."projectId" = pc."projectId"
   AND t."dueDate" IS NOT NULL
   AND t."dueDate" >= pc."startDate"
   AND t."dueDate" <= pc."endDate";

COMMIT;

-- ------------------------------------------------------------------
-- 2026-08-v3-phase5-review-loop.sql
-- ------------------------------------------------------------------

-- V3 Phase 5 — submit → review → approve/changes → post.
--
-- Structure (TaskDelivery.revision, the task_reviews table, the
-- ReviewDecision enum) is applied by `prisma db push`. This mirrors it and
-- carries the fold-in of the older ChangeRequest rows.
-- Idempotent — safe to re-run.

BEGIN;

-- ─────────────────────────────────────────────────────────────
-- v2's ChangeRequest could only say "please change this" — it had
-- no way to record an approval, which is why v3 replaces it with
-- TaskReview. Carry the existing rows across as round-1 change
-- requests so no feedback is lost. change_requests stays in place,
-- unused, for one release.
-- ─────────────────────────────────────────────────────────────
INSERT INTO task_reviews ("id", "taskId", "revision", "decision", "comments", "reviewedById", "reviewedAt")
SELECT
  'rev_' || cr.id,
  cr."taskId",
  1,
  'CHANGES_REQUESTED',
  cr.note,
  cr."requestedById",
  cr."createdAt"
FROM change_requests cr
WHERE NOT EXISTS (
  SELECT 1 FROM task_reviews tr WHERE tr.id = 'rev_' || cr.id
);

-- Every existing delivery was a first hand-in.
UPDATE task_deliveries SET revision = 1 WHERE revision IS NULL;

COMMIT;


-- ------------------------------------------------------------------
-- 2026-08-v3-phase6-cycle-close.sql
-- ------------------------------------------------------------------

-- V3 Phase 6 — cycle close: carry forward, extras, complimentary.
--
-- Structure (the billable_items table plus the BillableKind and
-- BillableStatus enums) is applied by `prisma db push`. This mirrors it.
-- Idempotent — safe to re-run.
--
-- There is no backfill: billable items are produced by CLOSING a cycle, and
-- no cycle has been closed before this phase existed. Cycles already marked
-- closed by hand (there should be none) would need their lines generated by
-- reopening and re-closing them through the wizard.

BEGIN;

-- Belt and braces: v2 marked over-delivery with isExtra only. Anything still
-- carrying that flag without a billing intent is a billable extra, so cycle
-- close offers it in step 3 rather than folding it silently into the package.
UPDATE content_items
   SET "billingIntent" = 'EXTRA_BILLABLE'
 WHERE "isExtra" = TRUE
   AND "billingIntent" = 'INCLUDED';

COMMIT;

-- ------------------------------------------------------------------
-- 2026-08-v3-phase7-invoicing.sql
-- ------------------------------------------------------------------

-- V3 Phase 7 — invoicing from closed cycles.
--
-- Structure (InvoiceLineItem.billableItemId, and COMPLIMENTARY / ADHOC_TASK
-- added to LineItemKind) is applied by `prisma db push`. This mirrors it.
-- Idempotent — safe to re-run.
--
-- Existing invoices are untouched: their lines keep kind CUSTOM/PACKAGE/EXTRA
-- and a null billableItemId, which is exactly right — they predate the
-- billing bridge and were never built from one.

BEGIN;

-- v2 marked complimentary lines with isFree and a zero price. v3 gives them
-- their own kind so the PDF can section them under "Complimentary" and show
-- the token amount rather than a silent zero. Only touches lines that are
-- unmistakably complimentary: free, but not a deliberate zero-rated custom
-- line the user typed themselves.
UPDATE invoice_line_items
   SET kind = 'COMPLIMENTARY'
 WHERE "isFree" = TRUE
   AND kind = 'EXTRA';

COMMIT;

-- ------------------------------------------------------------------
-- 2026-08-v3-fix-smm-designation.sql
-- ------------------------------------------------------------------

-- V3 correction — "SMM" was never a designation.
--
-- Phase 1 seeded a designation called SMM alongside a ROLE called SMM, so the
-- same word appeared in two adjacent columns meaning two different things.
-- An admin could read as "Admin / SMM" and nobody could say which was true.
--
-- The distinction v3 actually draws (docs/V3_CONTEXT.md §2):
--   Role        what you may DO      — OWNER, ADMIN, MANAGER, SMM, TEAM
--   Designation what you DO          — Editor, Photographer, Copywriter, …
--
-- Planning projects and reviewing work is an access tier, not a craft, so it
-- belongs to Role alone. Anyone who plans is role SMM; the label is redundant.
-- Idempotent — safe to re-run.

BEGIN;

-- Release anyone holding it. Their ROLE already says whether they plan.
UPDATE users u
   SET "designationId" = NULL
  FROM designations d
 WHERE u."designationId" = d.id
   AND d.slug = 'smm';

-- Then remove the label itself.
DELETE FROM designations WHERE slug = 'smm';

-- The same reasoning applies to "Head of Design": it IS a real job, so it
-- stays. Only SMM collided with a role name.

COMMIT;

-- ------------------------------------------------------------------
-- 2026-08-v3-drop-creative-type-emoji.sql
-- ------------------------------------------------------------------

-- Creative types are identified by colour, not emoji.
--
-- Phase 3 seeded an emoji into creative_types.icon for every default type
-- (Reel = clapperboard, Post = framed picture, and so on). Those rendered
-- across the calendar, the plan, the package tab and the review page.
--
-- Emoji draw differently on every OS, ignore the type's own colour, and read
-- as decoration in a tool people work in all day. Every creative type already
-- carries a colour, so the colour became the mark — see CreativeTypeDot.
--
-- The `icon` COLUMN stays: an agency that deliberately sets a lucide icon name
-- can still do so. Only the seeded emoji are cleared.
--
-- Idempotent — safe to re-run.

BEGIN;

UPDATE creative_types
   SET icon = NULL
 WHERE icon IS NOT NULL
   -- Anything outside plain ASCII is an emoji we seeded, never a lucide name.
   AND icon !~ '^[a-zA-Z0-9_-]+$';

COMMIT;

